/** Общие вопросы бренда (на странице тура показываются максимум эти + блок по конкретной поездке) */
export const faqs: FAQ[] = [
  {
    id: 'brand-booking',
    question: 'Как забронировать поездку?',
    answer:
      'Выберите маршрут на сайте и напишите нам в WhatsApp, Telegram или по телефону — подтвердим даты, наличие мест и условия.',
    tourSlug: null,
  },
  {
    id: 'brand-cancel',
    question: 'Можно ли отменить или перенести бронирование?',
    answer:
      'Условия отмены и переноса согласовываются при бронировании. Обычно возможен перенос или отмена при заблаговременном уведомлении — точные сроки фиксируются в договорённостях с вами.',
    tourSlug: null,
  },
];

export function getFaqsForTour(tour: Tour): FAQ[] {
  const brand = faqs.filter((f) => f.tourSlug === null);
  const diffLong: Record<Tour['difficulty'], string> = {
    easy: 'программа рассчитана на комфортный темп без специальной подготовки.',
    medium: 'возможны переходы и длительное время в дороге — ориентируйтесь на своё самочувствие.',
    hard: 'маршрут потребует хорошей физической формы — уточните детали у менеджера.',
  };
  const diffShort = { easy: 'простой', medium: 'средний', hard: 'сложный' }[tour.difficulty];
  const citiesList = tour.departureCities.map((c) => c.city).join(', ');

  const specifics: FAQ[] = [
    {
      id: `${tour.slug}-faq-pack`,
      question: 'Что взять с собой?',
      answer: `Удобная одежда и обувь по погоде${tour.durationDays > 1 ? ', вещи для ночлега по списку в программе' : ''}. Документы — см. ответ про паспорт ниже. Нюансы по маршруту в ${tour.destination} подскажет менеджер при бронировании.`,
      tourSlug: tour.slug,
    },
    {
      id: `${tour.slug}-faq-load`,
      question: 'Какая нагрузка на маршруте?',
      answer: `В карточке указана сложность: «${diffShort}». ${diffLong[tour.difficulty]}`,
      tourSlug: tour.slug,
    },
    {
      id: `${tour.slug}-faq-kids`,
      question: 'Можно ли с детьми?',
      answer:
        tour.minAge != null && tour.minAge >= 18
          ? `Эта программа рассчитана на взрослых (от ${tour.minAge} лет). Для поездок с детьми посмотрите другие маршруты на сайте.`
          : tour.minAge != null
            ? `Да, ориентир по возрасту — с ${tour.minAge} лет. Уточните у менеджера под вашу дату и состав группы.`
            : 'В большинстве поездок дети возможны; возраст и комфорт маршрута лучше согласовать при бронировании — зависит от конкретной программы.',
      tourSlug: tour.slug,
    },
    ...(tour.departureCities.length > 0
      ? [{
          id: `${tour.slug}-faq-dep`,
          question: 'Как проходит отправление?',
          answer: `Выезд заявлен из: ${citiesList}. Время и место сбора — в карточке города и в блоке «Организационная информация» на этой странице; после брони пришлём точные детали.`,
          tourSlug: tour.slug,
        }]
      : [{
          id: `${tour.slug}-faq-dep`,
          question: 'Как добраться до начала тура?',
          answer: 'Программа начинается по месту проведения. Мы поможем подобрать удобный вариант добора: поезд РЖД, авиаперелёт или другой маршрут до старта тура. Подскажем, как лучше состыковать дорогу с началом программы.',
          tourSlug: tour.slug,
        },
        {
          id: `${tour.slug}-faq-tickets`,
          question: 'Поможете с билетами до места начала тура?',
          answer: 'Да, мы помогаем подобрать удобный вариант добора до старта программы, в том числе поезда РЖД и другие подходящие маршруты. Подскажем оптимальное время прибытия и как состыковать дорогу с началом тура.',
          tourSlug: tour.slug,
        }]
    ),
    {
      id: `${tour.slug}-faq-meals`,
      question: 'Как организовано питание?',
      answer: `По этой поездке: ${tour.meals}`,
      tourSlug: tour.slug,
    },
    {
      id: `${tour.slug}-faq-free`,
      question: 'Сколько свободного времени?',
      answer:
        'Смотрите блок «Программа по дням»: там по дням расписаны экскурсии, переезды и паузы. Итоговый ритм дня уточняется у гида в начале тура.',
      tourSlug: tour.slug,
    },
    {
      id: `${tour.slug}-faq-docs`,
      question: 'Какие документы нужны?',
      answer:
        'Для поездок по России обычно достаточно паспорта гражданина РФ. Если в маршруте есть пересечение границы или особые объекты — список согласуем при бронировании.',
      tourSlug: tour.slug,
    },
  ];

  return [...brand, ...specifics];
}

// ============================================================================
// ФУНКЦИИ ДОСТУПА К ДАННЫМ
// ============================================================================

/**
 * Runtime source of truth for tours:
 * edit `data/tours.json` (e.g. via local admin panel) and site will use updates.
 */
const runtimeTours = toursJson as Tour[];

function getLocalTodayKey(): string {
  const now = new Date();
  const tzOffsetMs = now.getTimezoneOffset() * 60 * 1000;
  return new Date(now.getTime() - tzOffsetMs).toISOString().slice(0, 10);
}

function normalizeDateKey(value: string | undefined): string {
  if (!value) return '';
  return value.trim().slice(0, 10);
}

function getFutureDates(dates: Tour['nextDates'] | undefined): Tour['nextDates'] {
  if (!dates || dates.length === 0) return [];
  const todayKey = getLocalTodayKey();
  return dates
    .filter((d) => normalizeDateKey(d.start) >= todayKey)
    .sort((a, b) => normalizeDateKey(a.start).localeCompare(normalizeDateKey(b.start)));
}

function isTourActive(tour: Tour): boolean {
  const futureDates = getFutureDates(tour.nextDates);
  if (futureDates.length === 0) {
    // If no dates are provided, keep the tour visible (manual control via isPublished).
    return !tour.nextDates || tour.nextDates.length === 0;
  }

  return true;
}

export function getPublishedTours(): Tour[] {
  return runtimeTours
    .filter((t) => t.isPublished !== false && isTourActive(t))
    .map((t) => ({
      ...t,
      nextDates: getFutureDates(t.nextDates),
    }));
}

export function getToursByCity(citySlug: string): Tour[] {
  return getPublishedTours().filter((tour) =>
    tour.departureCities.length === 0 || tour.departureCities.some((dc) => dc.slug === citySlug)
  );
}

export function getDirectTourCountByCity(citySlug: string): number {
  return getPublishedTours().filter((tour) =>
    tour.departureCities.length > 0 && tour.departureCities.some((dc) => dc.slug === citySlug)
  ).length;
}

export function getTourBySlug(slug: string): Tour | undefined {
  return getPublishedTours().find((tour) => tour.slug === slug);
}

export function getTourById(id: string): Tour | undefined {
  return getPublishedTours().find((tour) => tour.id === id);
}

export function getCityBySlug(slug: string): City | undefined {
  return cities.find((city) => city.slug === slug);
}

function getTourDestinations(tour: Tour): string[] {
  return tour.destinations ?? [tour.destination];
}

export function getDestinationsByCity(citySlug: string): string[] {
  const cityTours = getToursByCity(citySlug);
  return [...new Set(cityTours.flatMap(getTourDestinations))];
}

/** Уникальные направления с турами из города + slug для ссылок на каталог и счётчик туров */
export function getDestinationChipsForCity(citySlug: string): { name: string; slug: string | null; count: number }[] {
  const cityTours = getToursByCity(citySlug);
  const byDest = new Map<string, number>();
  for (const t of cityTours) {
    for (const dest of getTourDestinations(t)) {
      byDest.set(dest, (byDest.get(dest) || 0) + 1);
    }
  }
  const rows = [...byDest.entries()].map(([name, count]) => {
    const d = destinations.find((x) => x.name.toLowerCase() === name.toLowerCase());
    return { name, slug: d?.slug ?? null, count };
  });
  rows.sort((a, b) => a.name.localeCompare(b.name, 'ru'));
  return rows;
}

export function getCitiesByRegion(): { region: string; cities: City[] }[] {
  const regionMap = new Map<string, City[]>();
  for (const city of cities) {
    const list = regionMap.get(city.region) || [];
    list.push(city);
    regionMap.set(city.region, list);
  }
  return Array.from(regionMap.entries()).map(([region, cities]) => ({ region, cities }));
}
